/**
 * MSW overrides for the event-submission endpoints (#383, Task 10).
 *
 * The defaults in `./handlers.ts` cover the happy path for both
 * CreateEventSubmission and ListMyEventSubmissions. A test that needs an
 * error response or a malformed `status` value says so explicitly via
 * `server.use(...)`, e.g.:
 *
 *   server.use(withMyEventSubmissionsError(403));
 *   server.use(withMyEventSubmissions([rawSubmission({ status: "bogus" })]));
 */
import { http, HttpResponse } from "msw";
import type { RawEventSubmission } from "../../src/api/eventSubmissions";
import { rawSubmission } from "../fixtures/eventSubmissions";

const CREATE_PATH = "/api/v1/range/exercises/:exerciseId/event-submissions";
const LIST_PATH = "/api/v1/range/exercises/:exerciseId/my-event-submissions";

/**
 * Override CreateEventSubmission's happy-path response body. Real BFF shape
 * is a DOUBLE envelope — `{ "data": { "submission": {...} } }` — writeJSON
 * always adds the outer `data` wrapper, and the handler additionally nests
 * the row under `submission` (see src/api/eventSubmissions.ts's module doc).
 */
export function withCreateEventSubmission(
  overrides: Partial<RawEventSubmission> = {},
) {
  return http.post(CREATE_PATH, () =>
    HttpResponse.json({ data: { submission: rawSubmission(overrides) } }, { status: 201 }),
  );
}

/** Make CreateEventSubmission fail with the given HTTP status. */
export function withCreateEventSubmissionError(status: number) {
  return http.post(CREATE_PATH, () => new HttpResponse(null, { status }));
}

/** Override ListMyEventSubmissions's happy-path response body. */
export function withMyEventSubmissions(
  submissions: readonly RawEventSubmission[] = [rawSubmission()],
) {
  return http.get(LIST_PATH, () => HttpResponse.json({ data: { submissions } }));
}

/** Make ListMyEventSubmissions fail with the given HTTP status. */
export function withMyEventSubmissionsError(status: number) {
  return http.get(LIST_PATH, () => new HttpResponse(null, { status }));
}


