/**
 * withExerciseStatus — MSW override for `GET /api/v1/range/exercises/:id`'s
 * `status` field (Task 10, #2012 MSW default-draft sweep).
 *
 * The default handler in `./handlers.ts` returns `status: "active"` — the
 * common case most tests want (execution-gated affordances unblocked). A
 * test that specifically needs a draft/paused/completed/archived exercise —
 * e.g. to exercise the `useExecutionGate` fail-closed path through a real
 * fetch, rather than via a hand-seeded `ExerciseStatusContext.Provider` —
 * says so explicitly:
 *
 *   server.use(withExerciseStatus("draft"));
 *
 * Only the `status` field changes; every other field keeps the same shape
 * the default handler returns, so a test overriding status doesn't also
 * have to re-specify the whole exercise fixture.
 */
import { http, HttpResponse } from "msw";
import type { ExerciseStatus } from "../../src/api/exercises";

export function withExerciseStatus(status: ExerciseStatus) {
  return http.get("/api/v1/range/exercises/:id", ({ params }) =>
    HttpResponse.json({
      data: {
        exercise: {
          id: params.id,
          name: "Op Aurora",
          status,
          description: "A test exercise",
          scenario_context: "",
          location_label: "Berlin",
          location_override_town: "",
          location_override_region: "",
          location_override_country: "",
          d_day: null,
          start_date: "2026-06-15T00:00:00Z",
          end_date: "2026-06-22T00:00:00Z",
          timezone: "America/New_York",
          created_by: "user-1",
          baseline_outlet_post_mode: "off",
          created_at: "2026-05-28T00:00:00Z",
          updated_at: "2026-05-28T00:00:00Z",
        },
      },
    }),
  );
}


--- frontends/range-mfe/tests/msw/handlers.ts (2007 lines) ---
/**
 * MSW handlers for range-mfe component tests.
 *
 * Default handlers provide happy-path responses for every BFF endpoint
 * touched by RangeApp. Individual tests can override a handler via
 * `server.use(...)` for error / edge-case scenarios.
 */

import { http, HttpResponse } from "msw";
import type { ArticleSearchHit, BaselineArticle, BaselineWebsite } from "../../src/api/baseline";
import type { AccountType } from "../../src/api/profiles";

export const handlers = [
  // GET /api/v1/range/exercises — exercise list.
  // The range-bff wraps list/get/create payloads in a { data: ... } envelope
  // (listExercises reads body.data); the fixture must mirror that shape.
  http.get("/api/v1/range/exercises", () =>
    HttpResponse.json({
      data: {
        exercises: [
          {
            id: "ex-1",
            name: "Op Aurora",
            status: "draft",
            description: "",
            scenario_context: "",
            location_label: "",
            location_override_town: "",
            location_override_region: "",
            location_override_country: "",
            d_day: null,
            created_at: "2026-05-28T00:00:00Z",
            updated_at: "2026-05-28T00:00:00Z",
          },
        ],
        next_page_token: "",
      },
    }),
  ),

  // POST /api/v1/range/exercises — create exercise (wizard launch).
  http.post("/api/v1/range/exercises", async ({ request }) => {
    const body = await request.json();
    const b = body as {
      name: string;
      description?: string;
      start_date?: string | null;
      end_date?: string | null;
      timezone?: string;
    };
    return HttpResponse.json(
      {
        data: {
          exercise: {
            id: "ex-new",
            name: b.name,
            status: "draft",
            description: b.description ?? "",
            scenario_context: "",
            location_label: "",
            location_override_town: "",
            location_override_region: "",
            location_override_country: "",
            d_day: null,
            start_date: b.start_date ?? null,
            end_date: b.end_date ?? null,
            timezone: b.timezone ?? "UTC",
            created_by: "u-1",
            baseline_outlet_post_mode: "off",
            created_at: "2026-05-28T00:00:00Z",
            updated_at: "2026-05-28T00:00:00Z",
          },
        },
      },
      { status: 201 },
    );
  }),

  // POST /api/v1/range/exercises/:id/status — setStatus (manual activation).
  http.post("/api/v1/range/exercises/:id/status", async ({ params, request }) => {
    const body = await request.json();
    const b = body as { status: string };
    return HttpResponse.json({
      data: {
        exercise: {
          id: params.id,
          name: "Op Iron Shield",
          status: b.status,
          description: "",
          scenario_context: "",
          location_label: "",
          location_override_town: "",
          location_override_region: "",
          location_override_country: "",
          d_day: null,
          baseline_outlet_post_mode: "off",
          created_at: "2026-05-28T00:00:00Z",
          updated_at: "2026-05-28T00:00:00Z",
        },
      },
    });
  }),

  // GET /api/v1/admin/users — org user list (creator-name resolution, pickers).
  http.get("/api/v1/admin/users", () =>
    HttpResponse.json({
      data: {
        users: [
          {
            keycloak_user_id: "user-1",
            display_name: "Maya Chen",
            email: "maya.chen@example.mil",
          },
          {
            keycloak_user_id: "u-1",
            display_name: "Maya Chen",
            email: "maya.chen@example.mil",
          },
        ],
      },
    }),
  ),

  // GET /api/v1/range/exercises/:id — single exercise (overview/settings).
  //
  // Default status is "active" (Task 10, #2012 MSW sweep) — NOT "draft".
  // Every execution-gated affordance (Trigger now, Post/Publish now,
  // Rebuild graph, baseline enable/sync, ...) reads this via
  // ExerciseStatusProvider → useExecutionGate, which fails closed while
  // loading/non-active. The large majority of tests mounting a gated screen
  // through this default handler assume an unblocked, "the exercise is
  // running" affordance — that's the common case, so it's the default.
  // A test that wants a draft/paused/completed exercise instead says so
  // explicitly via `withExerciseStatus(status)` (tests/msw/exerciseStatus.ts)
  // rather than inheriting an incidental draft from this fixture.
  http.get("/api/v1/range/exercises/:id", ({ params }) =>
    HttpResponse.json({
      data: {
        exercise: {
          id: params.id,
          name: "Op Aurora",
          status: "active",
          description: "A test exercise",
          scenario_context: "",
          location_label: "Berlin",
          location_override_town: "",
          location_override_region: "",
          location_override_country: "",
          d_day: null,
          start_date: "2026-06-15T00:00:00Z",
          end_date: "2026-06-22T00:00:00Z",
          timezone: "America/New_York",
          created_by: "user-1",
          baseline_outlet_post_mode: "off",
          created_at: "2026-05-28T00:00:00Z",
          updated_at: "2026-05-28T00:00:00Z",
        },
      },
    }),
  ),

  // GET /api/v1/range/exercises/:id/members — role roster (#285).
  // REAL wire shape (verified live against range-bff): each member carries
  // exercise_id + user_id (the Keycloak sub) + role ONLY — NO name, NO email.
  // Display names are resolved client-side (session self → org roster join →
  // localized "Unknown member" fallback).
  http.get("/api/v1/range/exercises/:id/members", ({ params }) =>
    HttpResponse.json({
      data: {
        members: [
          {
            exercise_id: String(params.id),
            user_id: "user-1",
            role: "range_admin",
          },
        ],
      },
    }),
  ),

  // POST /api/v1/range/exercises/:id/members — add member (#285) → 204
  http.post(
    "/api/v1/range/exercises/:id/members",
    () => new HttpResponse(null, { status: 204 }),
  ),

  // DELETE /api/v1/range/exercises/:id/members/:userId — remove member → 204
  http.delete(
    "/api/v1/range/exercises/:id/members/:userId",
    () => new HttpResponse(null, { status: 204 }),
  ),

  // GET /api/v1/range/exercises/:id/factions — faction list.
  // Faction epic (PR5): payload now carries influence + allies + adversaries +
  // member_count. The second faction omits allies/adversaries to exercise the
  // protojson empty-array defaulting in parseFaction.
  http.get("/api/v1/range/exercises/:id/factions", () =>
    HttpResponse.json({
      factions: [
        {
          id: "fac-1",
          org_id: "org-1",
          exercise_id: "ex-1",
          name: "Blue Force",
          description: "Friendly faction",
          stance_keywords: ["freedom", "defense"],
          profile_count: 10,
          is_published: false,
          created_at: "2026-05-28T00:00:00Z",
          influence: 60,
          allies: ["fac-2"],
          adversaries: [],
          member_count: 3,
        },
      ],
    }),
  ),

  // GET /api/v1/range/factions/:factionId — get single faction (detail route)
  http.get("/api/v1/range/factions/:factionId", ({ params }) =>
    HttpResponse.json({
      id: params.factionId,
      org_id: "org-1",
      exercise_id: "ex-1",
      name: "Blue Force",
      description: "Friendly faction",
      stance_keywords: ["freedom", "defense"],
      profile_count: 10,
      is_published: false,
      created_at: "2026-05-28T00:00:00Z",
      influence: 60,
      allies: ["fac-2"],
      adversaries: [],
      member_count: 3,
    }),
  ),

  // POST /api/v1/range/exercises/{id}/factions:draft — AI draft (colon-action;
  // anchored regex per the chi/path-to-regexp collision precedent).
  http.post(
    /\/api\/v1\/range\/exercises\/[^/]+\/factions:draft$/,
    () =>
      HttpResponse.json({
        name: "Coastal Separatists",
        description: "A regional autonomy movement seeking self-rule.",
        beliefs: ["autonomy", "self-rule", "regional identity"],
        influence: 55,
      }),
  ),

  // POST /api/v1/range/factions/:factionId/members — AddMembers (batch)
  http.post(
    "/api/v1/range/factions/:factionId/members",
    () => new HttpResponse(null, { status: 204 }),
  ),

  // DELETE /api/v1/range/factions/:factionId/members/:characterId — RemoveMember
  http.delete(
    "/api/v1/range/factions/:factionId/members/:characterId",
    () => new HttpResponse(null, { status: 204 }),
  ),

  // POST /api/v1/range/factions/:factionId/publish — Publish/Unpublish
  http.post(
    "/api/v1/range/factions/:factionId/publish",
    async ({ params, request }) => {
      const body = await request.json();
      // api/factions.ts sends { published: bool } (range-bff's wire key) — NOT
      // { publish }. Read the real field so toggling actually reflects intent.
      const b = body as { published?: boolean };
      return HttpResponse.json({
        id: params.factionId,
        org_id: "org-1",
        exercise_id: "ex-1",
        name: "Blue Force",
        description: "Friendly faction",
        stance_keywords: ["freedom", "defense"],
        profile_count: 10,
        is_published: b.published ?? true,
        created_at: "2026-05-28T00:00:00Z",
        influence: 60,
        allies: ["fac-2"],
        adversaries: [],
        member_count: 3,
      });
    },
  ),

  // POST /api/v1/range/exercises/:id/factions — create faction
  http.post("/api/v1/range/exercises/:id/factions", async ({ request }) => {
    const body = await request.json();
    const b = body as {
      name: string;
      description?: string;
      stance_keywords?: string[];
      profile_count?: number;
    };
    return HttpResponse.json(
      {
        id: "fac-new",
        org_id: "org-1",
        exercise_id: "ex-1",
        name: b.name,
        description: b.description ?? "",
        stance_keywords: b.stance_keywords ?? [],
        profile_count: b.profile_count ?? 20,
        is_published: false,
        created_at: "2026-05-28T00:00:00Z",
      },
      { status: 201 },
    );
  }),

  // PATCH /api/v1/range/factions/:factionId — update faction (singleton)
  http.patch(
    "/api/v1/range/factions/:factionId",
    async ({ params, request }) => {
      const patch = await request.json();
      const p = patch as { is_published?: boolean };
      return HttpResponse.json({
        id: params.factionId,
        org_id: "org-1",
        exercise_id: "ex-1",
        name: "Blue Force",
        description: "Friendly faction",
        stance_keywords: ["freedom", "defense"],
        profile_count: 10,
        is_published: p.is_published ?? false,
        created_at: "2026-05-28T00:00:00Z",
      });
    },
  ),

  // DELETE /api/v1/range/factions/:factionId (singleton)
  http.delete(
    "/api/v1/range/factions/:factionId",
    () => new HttpResponse(null, { status: 204 }),
  ),

  // POST /api/v1/range/factions/:factionId/generate-characters (singleton)
  http.post(
    "/api/v1/range/factions/:factionId/generate-characters",
    () => HttpResponse.json({ job_id: "job-1" }, { status: 202 }),
  ),

  // GET /api/v1/range/exercises/:id/characters — character list.
  // range-bff wraps the list payload in the { data: ... } envelope.
  http.get("/api/v1/range/exercises/:id/characters", () =>
    HttpResponse.json({
      data: {
        characters: [
          {
            id: "char-1",
            org_id: "org-1",
            exercise_id: "ex-1",
            faction_id: "fac-1",
            username: "agent_smith",
            display_name: "Agent Smith",
            avatar_url: "",
            bio: "A synthetic character aligned with Blue Force.",
            persona: "",
            is_synthetic: true,
            assigned_user_id: "",
            created_at: "2026-05-28T00:00:00Z",
          },
        ],
      },
    }),
  ),

  // POST /api/v1/range/characters/:charId/assign (singleton; empty user_id = unassign).
  // range-bff wraps the singleton payload in the { data: ... } envelope.
  http.post(
    "/api/v1/range/characters/:charId/assign",
    async ({ params, request }) => {
      const body = await request.json();
      const userId = (body as { user_id: string }).user_id;
      return HttpResponse.json({
        data: {
          id: params.charId,
          org_id: "org-1",
          exercise_id: "ex-1",
          faction_id: "fac-1",
          username: "agent_smith",
          display_name: "Agent Smith",
          avatar_url: "",
          bio: "A synthetic character.",
          persona: "",
          is_synthetic: true,
          assigned_user_id: userId,
          created_at: "2026-05-28T00:00:00Z",
        },
      });
    },
  ),

  // ─── Feed / Post routes (sub-PR 5) ──────────────────────────────────────

  // POST /api/v1/range/exercises/:id/feed/posts — create post
  http.post(
    "/api/v1/range/exercises/:exerciseId/feed/posts",
    async ({ params, request }) => {
      const body = await request.json();
      const b = body as { character_id: string; body: string };
      // range-bff CreatePost → writeJSON(.., {"post": ...}) → { data: { post } }.
      return HttpResponse.json(
        {
          data: {
            post: {
              id: "post-new",
              org_id: "org-1",
              exercise_id: params.exerciseId,
              character_id: b.character_id,
              parent_post_id: null,
              body: b.body,
              typology: "post",
              is_ai_generated: false,
              is_deleted: false,
              authored_by_user: "u-1",
              created_at: "2026-05-29T00:00:00Z",
              like_count: 0,
              repost_count: 0,
              reply_count: 0,
              mentions: [],
              faction_color: "#3B82F6",
              author_username: "alice",
            },
          },
        },
        { status: 201 },
      );
    },
  ),

  // GET /api/v1/range/exercises/:id/feed — list feed.
  // range-bff wraps the list payload in the { data: ... } envelope.
  http.get("/api/v1/range/exercises/:exerciseId/feed", () =>
    HttpResponse.json({
      data: {
        posts: [
          {
            id: "post-1",
            org_id: "org-1",
            exercise_id: "ex-1",
            character_id: "char-1",
            parent_post_id: null,
            body: "Hello @ai_agent what do you think?",
            typology: "post",
            is_ai_generated: false,
            is_deleted: false,
            authored_by_user: "u-1",
            created_at: "2026-05-29T00:00:00Z",
            like_count: 2,
            repost_count: 1,
            reply_count: 0,
            mentions: ["char-ai-1"],
            faction_color: "#3B82F6",
            author_username: "alice",
          },
          {
            id: "post-ai-1",
            org_id: "org-1",
            exercise_id: "ex-1",
            character_id: "char-ai-1",
            parent_post_id: "post-1",
            body: "The scenario is concerning — we should review the response protocol.",
            typology: "reply",
            is_ai_generated: true,
            is_deleted: false,
            authored_by_user: null,
            created_at: "2026-05-29T00:00:05Z",
            like_count: 0,
            repost_count: 0,
            reply_count: 0,
            mentions: ["char-1"],
            faction_color: "#EF4444",
            author_username: "ai_agent",
          },
        ],
        next_page_token: "",
      },
    }),
  ),

  // GET /api/v1/range/posts/:postId — get single post.
  // range-bff wraps the get payload in the { data: ... } envelope.
  http.get("/api/v1/range/posts/:postId", ({ params }) =>
    HttpResponse.json({
      data: {
        post: {
          id: params.postId,
          org_id: "org-1",
          exercise_id: "ex-1",
          character_id: "char-1",
          parent_post_id: null,
          body: "Test post body",
          typology: "post",
          is_ai_generated: false,
          is_deleted: false,
          authored_by_user: "u-1",
          created_at: "2026-05-29T00:00:00Z",
          like_count: 2,
          repost_count: 0,
          reply_count: 1,
          mentions: [],
          faction_color: "#3B82F6",
          author_username: "alice",
        },
      },
    }),
  ),

  // POST /api/v1/range/posts/{postId}:reply — create reply.
  //
  // chi colon-actions like `:reply`/`:like`/`:unlike`/`:repost` collide
  // with MSW's path-to-regexp param parser ("two parameters with no text
  // between" — TypeError at handler-registration time). Match the URL
  // with a regex anchored on the trailing literal action so the path
  // string never goes through path-to-regexp.
  http.post(
    /\/api\/v1\/range\/posts\/[^/]+:reply$/,
    async ({ request }) => {
      const body = await request.json();
      const b = body as { character_id: string; body: string };
      const url = new URL(request.url);
      const postIdMatch = url.pathname.match(/\/posts\/([^/]+):reply$/);
      const postId = postIdMatch?.[1] ?? "";
      // range-bff Reply → writeJSON(.., {"post": ...}) → { data: { post } }.
      return HttpResponse.json(
        {
          data: {
            post: {
              id: "post-reply-1",
              org_id: "org-1",
              exercise_id: "ex-1",
              character_id: b.character_id,
              parent_post_id: postId,
              body: b.body,
              typology: "reply",
              is_ai_generated: false,
              is_deleted: false,
              authored_by_user: "u-1",
              created_at: "2026-05-29T00:01:00Z",
              like_count: 0,
              repost_count: 0,
              reply_count: 0,
              mentions: [],
              faction_color: "#3B82F6",
              author_username: "alice",
            },
          },
        },
        { status: 201 },
      );
    },
  ),

  // POST /api/v1/range/posts/{postId}:repost
  http.post(
    /\/api\/v1\/range\/posts\/[^/]+:repost$/,
    () => new HttpResponse(null, { status: 204 }),
  ),

  // POST /api/v1/range/posts/{postId}:like
  http.post(
    /\/api\/v1\/range\/posts\/[^/]+:like$/,
    () => new HttpResponse(null, { status: 204 }),
  ),

  // POST /api/v1/range/posts/{postId}:unlike
  http.post(
    /\/api\/v1\/range\/posts\/[^/]+:unlike$/,
    () => new HttpResponse(null, { status: 204 }),
  ),

  // DELETE /api/v1/range/posts/:postId
  http.delete(
    "/api/v1/range/posts/:postId",
    () => new HttpResponse(null, { status: 204 }),
  ),

  // GET /api/v1/range/posts/:postId/interactions.
  // range-bff wraps the list payload in the { data: ... } envelope.
  http.get("/api/v1/range/posts/:postId/interactions", ({ params }) =>
    HttpResponse.json({
      data: {
        interactions: [
          {
            id: "int-1",
            post_id: params.postId,
            character_id: "char-1",
            kind: "like",
            created_at: "2026-05-29T00:00:00Z",
          },
        ],
        next_page_token: "",
      },
    }),
