  // GET /api/v1/range/exercises/:id/baseline/search — SearchArticles for Serp.
  // Filters BASELINE_ARTICLES by case-insensitive substring match on title+excerpt,
  // returns ArticleSearchHit[] with <mark>-highlighted headline_snippet.
  http.get("/api/v1/range/exercises/:id/baseline/search", ({ request }) => {
    const url = new URL(request.url);
    const q = (url.searchParams.get("q") ?? "").trim().toLowerCase();
    if (q === "") {
      return HttpResponse.json({ data: { hits: [], next_page_token: "" } });
    }
    const hits: ArticleSearchHit[] = [];
    for (const article of BASELINE_ARTICLES.values()) {
      const inTitle = article.title.toLowerCase().includes(q);
      const inExcerpt = article.excerpt.toLowerCase().includes(q);
      if (!inTitle && !inExcerpt) continue;
      const website = BASELINE_WEBSITES.get(article.baseline_website_id);
      if (!website) continue;
      const headlineSnippet = inTitle
        ? article.title.replace(
            new RegExp(`(${q.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")})`, "gi"),
            "<mark>$1</mark>",
          )
        : article.title;
      hits.push({
        article,
        headline_snippet: headlineSnippet,
        website_name: website.name,
        website_domain: website.domain_slug,
        rank: inTitle ? 1.0 : 0.5,
      });
    }
    hits.sort((a, b) => b.rank - a.rank);
    return HttpResponse.json({ data: { hits, next_page_token: "" } });
  }),

